105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        List<String> missingFields = new ArrayList<>();
109	        if (isBlank(ownerFieldsDto.getFirstName())) {
110	            missingFields.add("firstName");
111	        }
112	        if (isBlank(ownerFieldsDto.getLastName())) {
113	            missingFields.add("lastName");
114	        }
115	        if (isBlank(ownerFieldsDto.getAddress())) {
116	            missingFields.add("address");
117	        }
118	        if (isBlank(ownerFieldsDto.getCity())) {
119	            missingFields.add("city");
120	        }
121	        if (isBlank(ownerFieldsDto.getTelephone())) {
122	            missingFields.add("telephone");
123	        }
124	        if (!missingFields.isEmpty()) {
125	            throw new InvalidOwnerFieldsException(missingFields);
126	        }
127	        // Normalize the telephone into E.164 form; a number that cannot form a valid
128	        // E.164 value is rejected with a 400.
129	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
130	        // Email is optional; when present it must be a syntactically valid address and is
131	        // stored lower-cased. An invalid address is rejected with a 400.
132	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
133	        // Reject the request if the E.164 telephone is already used by any other owner.
134	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
135	            .map(Owner::getTelephone)
136	            .filter(existing -> existing != null)
137	            .anyMatch(normalizedTelephone::equals);
138	        if (telephoneInUse) {
139	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
140	        }
141	        // Reject the request when another owner already shares this last name and address (compared
142	        // case-insensitively with collapsed whitespace), unless the caller explicitly opts in by
143	        // setting 'sharesHousehold' true.
144	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
145	            String normalizedLastName = collapse(ownerFieldsDto.getLastName());
146	            String normalizedAddress = collapse(ownerFieldsDto.getAddress());
147	            boolean householdInUse = this.clinicService.findAllOwners().stream()
148	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
149	                    && collapse(existing.getAddress()).equals(normalizedAddress));
150	            if (householdInUse) {
151	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
152	            }
153	        }
154	        HttpHeaders headers = new HttpHeaders();
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        owner.setTelephone(normalizedTelephone);
157	        owner.setEmail(normalizedEmail);
158	        // When no registration date is supplied, default it to the server's current date.
159	        if (owner.getRegistrationDate() == null) {
160	            owner.setRegistrationDate(LocalDate.now());
161	        }
162	        // Assign the customer code: '<LAST3>-<NNNN>' where LAST3 is the upper-cased first three
163	        // letters of the last name and NNNN is a global 4-digit zero-padded sequence equal to one
164	        // more than the current number of owners.
165	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
166	        this.clinicService.saveOwner(owner);
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
