267	    private static boolean isBlank(String value) {
268	        return value == null || value.trim().isEmpty();
269	    }
270	
271	    /**
272	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
273	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
274	     * compared case-insensitively with collapsed whitespace.
275	     */
276	    private static String collapse(String value) {
277	        if (value == null) {
278	            return "";
279	        }
280	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
281	    }
282	
283	    /**
284	     * Build the customer code for a new owner: {@code '<LAST3>-<NNNN>'} where LAST3 is the
285	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
286	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
287	     */
288	    private String nextCustomerCode(String lastName) {
289	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
290	        long sequence = this.clinicService.findAllOwners().size() + 1L;
291	        return String.format("%s-%04d", last3, sequence);
292	    }
293	
294	    /**
295	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
296	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
297	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
298	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
299	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
300	     */
301	    private static String toE164(String raw) {
302	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
303	        boolean hasCountryCode = cleaned.startsWith("+");
304	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
305	        if (!digits.matches("\\d+")) {
306	            throw new InvalidOwnerFieldsException(List.of("telephone"));
307	        }
308	        if (!hasCountryCode) {
309	            if (digits.startsWith("0")) {
310	                digits = digits.substring(1);
311	            }
312	            digits = "61" + digits;
313	        }
314	        if (digits.length() < 8 || digits.length() > 15) {
315	            throw new InvalidOwnerFieldsException(List.of("telephone"));
316	        }
317	        return "+" + digits;
318	    }
319	
320	    /**
321	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
322	     * and a domain with at least one dot-separated label, none of which contain whitespace or
323	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
324	     */
325	    private static final Pattern EMAIL_PATTERN =
326	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
327	
328	    /**
329	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
330	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
331	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
332	     * 400. A valid address is returned lower-cased.
333	     */
334	    private static String normalizeEmail(String email) {
335	        if (email == null || email.isEmpty()) {
336	            return null;
337	        }
338	        String trimmed = email.trim();
339	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
340	            throw new InvalidOwnerFieldsException(List.of("email"));
341	        }
342	        return trimmed.toLowerCase();
343	    }
344	}
