21	/**
22	 * Thrown when a request to create or edit an owner is missing or blank in one or more
23	 * required fields. Carries the names of the offending fields so the REST response can
24	 * report exactly which fields were rejected.
25	 */
26	public class InvalidOwnerFieldsException extends RuntimeException {
27	
28	    private final List<String> fields;
29	
30	    public InvalidOwnerFieldsException(List<String> fields) {
31	        super("Missing or blank required owner fields: " + fields);
32	        this.fields = List.copyOf(fields);
33	    }
34	
35	    public List<String> getFields() {
36	        return this.fields;
37	    }
38	}
